internal object DuaElDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Καταφύγιο από έναν κακό γείτονα", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από έναν κακό γείτονα στον τόπο μόνιμης κατοικίας, γιατί ο γείτονας σε ένα ταξίδι προχωρά.", "Για προστασία από έναν κακό γείτονα.", "Ο Προφήτης ﷺ διέταξε να αναζητήσει καταφύγιο από αυτό."),
        "dua_ishfi_abdak" to DuaText("Για την ανάρρωση ενός άρρωστου", "Ω Αλλάχ, θεράπευσε τον δούλο Σου για να αντιμετωπίσει έναν εχθρό για Σένα ή να περπατήσει για να προσευχηθεί για Σένα.", "Για τον άρρωστο όταν τον επισκέπτεται.", "Ο Προφήτης ﷺ δίδαξε λέγοντας αυτό για τους άρρωστους."),
        "dua_la_mania" to DuaText("Κανείς δεν μπορεί να σας κρατήσει αυτό που δίνετε", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος, και έχει δύναμη πάνω σε όλα τα πράγματα. Ω Αλλάχ, κανείς δεν μπορεί να συγκρατήσει ό,τι δίνεις και κανείς δεν μπορεί να δώσει ό,τι κρατάς, και ο πλούτος των πλουσίων δεν ωφελεί εναντίον Σου.", "Μετά το σαλάμι της υποχρεωτικής προσευχής.", "Ο Προφήτης ﷺ το είπε αυτό μετά από κάθε υποχρεωτική προσευχή."),
        "dua_slaughtering" to DuaText("Όταν σφάζετε ένα ζώο", "Στο όνομα του Αλλάχ, και ο Αλλάχ είναι ο Μεγαλύτερος.", "Κατά τη θυσία ή τη σφαγή ενός ζώου.", "Ο Προφήτης ﷺ είπε Bismillah και takbir την ώρα της θυσίας."),
        "dua_undressing" to DuaText("Όταν βγάζετε τα ρούχα", "Στο όνομα του Αλλάχ.", "Όταν βγάζετε ρούχα (για γκουσλ ή αλλαγή).", "Γίνεται μια οθόνη ανάμεσα στα μάτια των τζιν και στα ιδιωτικά μέρη ενός ατόμου."),
        "dua_ilbas_jadidan" to DuaText("Βλέποντας κάποιον με καινούργια ρούχα", "Φορέστε καινούργια, ζήστε αξιέπαινα και πέθανε μάρτυρας.", "Βλέποντας έναν μουσουλμάνο αδελφό με καινούργια ρούχα.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά όταν είδε τον Ουμάρ (RA) με καινούργια ρούχα."),
        "dua_hajj_la_riya" to DuaText("Χατζ χωρίς επίδειξη", "Ω Αλλάχ, (κάντε το) ένα Χατζ χωρίς επίδειξη και χωρίς αναζήτηση φήμης.", "Για ειλικρίνεια όταν κάνετε την πρόθεση για Χατζ.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουέτα την ώρα του Χατζ."),
        "dua_q_muslimayni_laka" to DuaText("Dua of Ibrahim & Ismail (AS) — Κάντε μας υποτακτικούς", "Κύριε μας, κάνε μας υποταγμένους σε Σένα και από τους απογόνους μας ένα έθνος υποταγμένο σε Σένα. Δείξε μας τις τελετουργίες της λατρείας μας και αποδέξου τη μετάνοιά μας. Πράγματι, Εσύ είσαι ο Αποδέκτης της μετάνοιας, ο Ελεήμων.", "Δούα υποταγής για τον εαυτό του και τους απογόνους του.", "Η ντουά που έγινε κατά την κατασκευή της Κάαμπα."),
        "dua_q_iftah_baynana" to DuaText("Dua of Shu'aib (AS) — Δικαστής μεταξύ μας", "Κύριε μας, κρίνε ανάμεσά μας και τον λαό μας με αλήθεια, και εσύ είσαι ο καλύτερος από τους κριτές.", "Για μια κρίση μεταξύ αλήθειας και ψεύδους.", "Η ντουά του Σουάιμπ (AS) όταν οι άνθρωποι του τον απέρριψαν."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua of Musa (AS) — Ποτέ βοηθός εγκληματιών", "Κύριε μου, λόγω της χάρης που μου έκανες, δεν θα γίνω ποτέ βοηθός των εγκληματιών.", "Ευγνωμοσύνη για τις ευλογίες του Αλλάχ και μια υπόσχεση να μην βοηθήσουμε τους αδικημένους.", "Το όρκο του Μούσα (AS) μετά τη μετάνοιά του."),
        "dua_q_nuh_unsurni" to DuaText("Dua of Nuh (AS) — Βοήθησέ με, με αρνούνται", "Κύριε μου, βοήθησέ με, γιατί με έχουν αρνηθεί.", "Όταν οι άνθρωποι σε αρνούνται και απορρίπτουν την αλήθεια.", "Η ντουά του Nuh (AS), η οποία απαντήθηκε."),
        "dua_q_ihkum_bil_haqq" to DuaText("Κύριε μου, κρίνετε με την αλήθεια", "Κύριε μου, κρίνετε με την αλήθεια. Και ο Κύριός μας είναι ο Ελεήμων, του οποίου ζητείται βοήθεια ενάντια σε αυτά που περιγράφετε.", "Μπροστά στα ψέματα και τις ψευδείς κατηγορίες.", "Μια ντουέτα που διδάχθηκε στον Προφήτη ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Καταφύγιο από το συντριπτικό χρέος και τους εχθρούς", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από το να με κατακλύσει το χρέος, να μην με κυριεύσει ένας εχθρός και από τη δοξολογία των εχθρών.", "Προστασία από το βάρος του χρέους και την κυριαρχία των εχθρών.", "Ο Προφήτης ﷺ αναζητούσε καταφύγιο από αυτά τα πράγματα."),
        "dua_faqr_qillah_dhillah" to DuaText("Καταφύγιο από τη φτώχεια και την ταπείνωση", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από τη φτώχεια, τη σπανιότητα και την ταπείνωση, και από το να αδικήσω τους άλλους ή να αδικηθώ.", "Να είσαι ασφαλής από τις κακουχίες, την επιθυμία και την ταπείνωση.", "Ένα καταφύγιο που διδάχθηκε από τον Προφήτη ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Συγχώρεσε, Έλεος, Καθοδήγησε, Θεράπευσε, Πρόσφερε", "Ω Αλλάχ, συγχώρεσέ με, ελέησέ με, καθοδήγησέ με, δώσε μου ευημερία και φρόντισέ με.", "Ο Προφήτης ﷺ δίδαξε αυτή τη ντουέτα, μαζί με την προσευχή, σε νέους μουσουλμάνους.", "Ο Προφήτης ﷺ είπε: αυτά τα λόγια συγκεντρώνουν για σένα αυτόν τον κόσμο και το επέκεινα."),
        "dua_ruku_laka_raka_tu" to DuaText("Στο Ruku — Σε σένα υποκλίθηκα", "Ω Αλλάχ, σε Σένα υποκλίθηκα, σε σένα πίστεψα και σε σένα υποτάχτηκα. Η ακοή μου, η όρασή μου, ο νους μου, τα οστά μου και τα νεύρα μου ταπεινώνονται μπροστά Σου.", "Στο ρούκου (ιδιαίτερα στις εθελοντικές προσευχές).", "Ο Προφήτης ﷺ το απήγγειλε αυτό στο ρούκου."),
        "dua_sujood_laka_sajadtu" to DuaText("Στο Σουτζούντ — Σε Σένα προσκύνησα", "Ω Αλλάχ, σε Σένα έχω προσκυνήσει, σε σένα πίστεψα και σε σένα υποτάχτηκα. Το πρόσωπό μου έχει προσκυνήσει Εκείνον που το δημιούργησε, το διαμόρφωσε και του έφερε την ακοή και την όρασή του. Ευλογημένος είναι ο Αλλάχ, ο καλύτερος δημιουργός.", "Στο sujood (ειδικά στις εθελοντικές προσευχές).", "Ο Προφήτης ﷺ το απήγγειλε αυτό στο sujood."),
        "dua_ruku_sujood_subhanaka" to DuaText("Δόξα σε Σένα, Κύριέ μας — Συγχώρεσέ με", "Δόξα σε Σένα, ω Αλλάχ, Κύριέ μας, και δόξα σε Σένα. Ω Αλλάχ, συγχώρεσέ με.", "Σε ρούκου και σουτζούντ.", "Aisha (RA): ο Προφήτης ﷺ το έλεγε συχνά αυτό σε ruku και sujood."),
        "dua_q_musa_li_akhi" to DuaText("Dua of Musa (AS) — Συγχώρεσέ με και τον αδερφό μου", "Κύριε μου, συγχώρεσέ εμένα και τον αδελφό μου και παραδέξου μας στο έλεός Σου, γιατί Εσύ είσαι ο Ελεήμων από τους ελεήμονες.", "Συγχώρεση για τον εαυτό του και τον αδερφό ή τα αγαπημένα του πρόσωπα.", "Η ντουά του Μούσα (AS) για τον Χαρούν (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Αναθέτω την Υπόθεσή Μου στον Αλλάχ", "Και εμπιστεύομαι την υπόθεση μου στον Αλλάχ. Πράγματι, ο Αλλάχ βλέπει τα πάντα στους υπηρέτες Του.", "Όταν οι άνθρωποι σας αντιτίθενται και το θέμα πρέπει να αφεθεί στον Αλλάχ.", "Τα λόγια του πιστού από το λαό του Φαραώ. Τότε ο Αλλάχ τον προστάτεψε από τις κακές τους επιβουλές."),
        "dua_q_hawariyyun" to DuaText("Δόξα των Μαθητών — Καταγράψτε μας με τους Μάρτυρες", "Κύριε μας, πιστέψαμε σε αυτό που αποκάλυψες και ακολουθήσαμε τον Αγγελιοφόρο, οπότε καταγράψτε μας στους μάρτυρες.", "Για σταθερότητα στην πίστη και στην ακολουθία του Αγγελιοφόρου.", "Η δόξα των μαθητών του Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua of Ibrahim (AS) — Μην με ντροπιάζεις", "Και μη με ντροπιάζεις την ημέρα που θα αναστηθούν.", "Για να είμαστε ασφαλείς από την ατιμία την ημέρα της Ανάστασης.", "Η ντουά του Ιμπραήμ (AS) για το εξής."),
        "dua_iftar_laka_sumtu" to DuaText("Ιφτάρ — Για σένα Νήστεψα", "Ω Αλλάχ, για σένα νήστεψα και με την προμήθεια Σου διακόπτω τη νηστεία μου.", "Κατά το διάλειμμα της νηστείας (το γνωστό iftar dua).", "Ο Προφήτης ﷺ το είπε αυτό στο ιφτάρ. Είναι μια αφήγηση που ενισχύεται από άλλες αφηγήσεις. η απαγγελία του στο ιφτάρ είναι η πρακτική των Χαναφί και της πλειοψηφίας."),
        "dua_iftar_ibn_umar" to DuaText("Ιφτάρ — Με το απέραντο έλεός σου, συγχώρεσέ με", "Ω Αλλάχ, Σου ζητώ με το έλεός Σου που περιλαμβάνει όλα τα πράγματα να με συγχωρήσεις.", "Στο ιφτάρ — ο Abdullah ibn Amr (RA) έκανε αυτή τη ντουά. η ντουά του νηστεύοντος στο ιφτάρ δεν απορρίπτεται.", "Χαντίθ: η ντουά του νηστεύοντος την ώρα του ιφτάρ δεν απορρίπτεται."),
        "dua_inni_saim" to DuaText("Όταν προκαλείται κατά τη νηστεία", "νηστεύω, νηστεύω.", "Όταν κάποιος σε προσβάλλει ή σε καβγαδίζει ενώ νηστεύεις.", "Ο Προφήτης ﷺ είπε: η νηστεία είναι ασπίδα, επομένως ο νηστευτής δεν πρέπει να μιλάει άσεμνα ή να ενεργεί με άγνοια — αν κάποιος τσακωθεί, πείτε αυτό δύο φορές."),
        "dua_eid_takbeer" to DuaText("Takbeer στο δρόμο για το Eid", "Ο Αλλάχ είναι ο Μεγαλύτερος, ο Αλλάχ είναι ο Μεγαλύτερος, δεν υπάρχει θεός εκτός από τον Αλλάχ, και ο Αλλάχ είναι ο Μεγαλύτερος, ο Αλλάχ είναι ο Μεγαλύτερος, και όλος ο έπαινος είναι για τον Αλλάχ.", "Από τη νύχτα της σελήνης μέχρι την προσευχή του Eid al-Fitr, ειδικά στο δρόμο προς το έδαφος του Eid.", "Η εντολή του Κορανίου: «ώστε να ολοκληρώσετε την καταμέτρηση και να διακηρύξετε το μεγαλείο του Αλλάχ» (αλ-Μπακάρα 2:185). Ο Ibn Mas'ud (RA) είπε αυτό το τακμπίρ."),
        "dua_ahsin_aqibatana" to DuaText("Κάντε το τέλος μας καλό σε όλες τις υποθέσεις", "Ω Αλλάχ, κάνε το τέλος μας καλό σε όλες τις υποθέσεις και προστάτεψε μας από την ντροπή στον κόσμο και την τιμωρία στο επέκεινα.", "Για καλό αποτέλεσμα σε κάθε θέμα.", "Όποιος κάνει αυτή τη ντουέτα και πεθάνει πριν δικαστεί, πεθαίνει (ασφαλής από τη δοκιμασία)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Ζητώ την γενναιοδωρία και το έλεός Σου", "Ω Αλλάχ, Σου ζητώ τη γενναιοδωρία και το έλεός Σου, γιατί κανείς δεν τα κατέχει εκτός από Εσένα.", "Όταν ζητάς πρόνοια και έλεος.", "Οι επισκέπτες ήρθαν στον Προφήτη ﷺ όταν δεν υπήρχε φαγητό. έκανε αυτή τη ντουά, και μετά έφτασε ένα δώρο."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Λέξεις που διδάσκονται σε έναν Βεδουίνο", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Ο Αλλάχ είναι ο Μεγαλύτερος, σε μεγάλο βαθμό. Ο άφθονος έπαινος είναι για τον Αλλάχ. Δόξα στον Αλλάχ, τον Κύριο των κόσμων. και δεν υπάρχει ισχύς ούτε δύναμη παρά μόνο με τον Αλλάχ, τον Παντοδύναμο, τον Σοφό.", "Μια περιεκτική φράση του dhikr και της ντουά - διδάσκεται σε έναν Βεδουίνο.", "Μετά από αυτό διδάχτηκε να λέει «Allahummaghfir li warhamni wahdini warzuqni»."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Συγχωρέστε όσα έστειλα πριν και μετά", "Ω Αλλάχ, συγχώρεσε με τις αμαρτίες που έκανα πριν και μετά, τι έκανα στα κρυφά και ό,τι έκανα φανερά, τις υπερβολές μου και τι ξέρεις καλύτερα από εμένα. Είσαι Αυτός που φέρνει μπροστά και Αυτός που Βάζει πίσω. δεν υπάρχει θεός εκτός από Εσένα.", "Μετά το tashahhud και το salawat, πριν το σαλάμ.", "Ο Προφήτης ﷺ το απήγγειλε αυτό στο τέλος της προσευχής, μεταξύ του tashahhud και του σαλάμ."),
        "dua_jiddi_wa_hazli" to DuaText("Συγχωρέστε τη σοβαρότητά μου και το αστείο μου", "Ω Αλλάχ, συγχώρεσε με τις αμαρτίες που διέπραξα σοβαρά και αστεία, κατά λάθος και εσκεμμένα — και όλα αυτά είναι μέσα μου.", "Συγχώρεση για κάθε είδους αμαρτία, γνωστή και άγνωστη.", "Ένα περιεκτικό ιστιγφάρ του Προφήτη ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Μετά το Ρούκου — Έπαινος που γεμίζει τους ουρανούς", "Κύριε μας, σε Σένα ανήκει όλος ο έπαινος, γεμίζοντας τους ουρανούς, γεμίζοντας τη γη και γεμίζοντας ό,τι άλλο θέλεις μετά από αυτό.", "Αφού σηκώθηκε από το ρούκου, μαζί με το 'Rabbana lakal-hamd'.", "Ο Προφήτης ﷺ το είπε αυτό όταν σηκώθηκε από το ρούκου."),
        "dua_istiftah_kabira" to DuaText("Ο Αλλάχ είναι ο Μεγαλύτερος, Επαινείται άφθονα", "Ο Αλλάχ είναι ο Μεγαλύτερος, σε μεγάλο βαθμό. Ο άφθονος έπαινος είναι για τον Αλλάχ. και δόξα να είναι ο Αλλάχ πρωί και βράδυ.", "Κατά την έναρξη της προσευχής (μία μορφή του εναρκτηρίου έπαινο).", "Ο Προφήτης ﷺ είπε: οι πύλες του ουρανού άνοιξαν γι' αυτό."),
        "dua_q_ashku_bathhi" to DuaText("Dua of Yaqub (AS) — Παραπονιέμαι μόνο στον Αλλάχ", "Παραπονιέμαι για την αγωνία και τη θλίψη μου μόνο στον Αλλάχ.", "Σε βαθιά θλίψη και χωρισμό.", "Ο Ya'qub (AS) το είπε αυτό στον χωρισμό του από τον Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Ο Αλλάχ είναι ο καλύτερος προστάτης", "Ο Αλλάχ είναι ο καλύτερος προστάτης και είναι ο πιο ελεήμων από τους ελεήμονες.", "Όταν στέλνετε παιδιά ή αγαπημένα πρόσωπα σε ένα ταξίδι.", "Ο Γιακούμπ (AS) το είπε αυτό ενώ εμπιστεύτηκε τον γιο του στον Αλλάχ."),
        "dua_q_aqraba_rashada" to DuaText("Είθε ο Κύριός μου να με καθοδηγήσει πιο κοντά στα δεξιά", "Ίσως ο Κύριός μου να με καθοδηγήσει σε ό,τι είναι πιο κοντά από αυτό στην ορθή συμπεριφορά.", "Όταν αναζητάτε έναν καλύτερο τρόπο σε κάποιο θέμα.", "Ο Προφήτης ﷺ είπε να το πει αυτό μόλις το ξεχάσει."),
        "dua_q_sawa_as_sabil" to DuaText("Dua of Musa (AS) — Οδηγήστε με στον σωστό δρόμο", "Ίσως ο Κύριός μου με καθοδηγήσει στον σωστό δρόμο.", "Όταν ξεκινάτε ένα νέο ταξίδι ή έναν άγνωστο δρόμο.", "Ο Musa (AS) είπε αυτό καθώς στράφηκε προς το Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Μην με τοποθετείτε ανάμεσα σε αδικοπραγμένους", "Κύριε μου, μη με βάζεις ανάμεσα στους αδικημένους ανθρώπους.", "Μια ντουέτα που ζητά από τον Αλλάχ να κρατήσει έναν χωριστά από τους αδίκους.", "Μια ντουέτα που ζητά από τον Αλλάχ να κρατήσει έναν χωριστά από τους αδίκους."),
        "dua_q_do_not_make_us_trial" to DuaText("Μην μας κάνετε Δοκιμή", "Κύριε μας, μη μας κάνεις δοκιμασία για τους απίστους, και συγχώρεσέ μας, Κύριε μας. Πράγματι, Εσύ είσαι ο Παντοδύναμος, ο Σοφός.", "Η ντουέτα του Ιμπραήμ (AS) και των συντρόφων του.", "Η ντουέτα του Ιμπραήμ (AS) και των συντρόφων του."),
        "dua_morning_witness" to DuaText("Πρωινός μάρτυρας του Tawhid", "Ω Αλλάχ, μπήκα το πρωί καλώντας Εσένα, τους φορείς του Θρόνου Σου, τους αγγέλους Σου και όλη τη δημιουργία Σου για να μαρτυρώ ότι είσαι ο Αλλάχ, δεν υπάρχει θεός εκτός από Σένα, μόνος, χωρίς σύντροφο, και ότι ο Μωάμεθ ﷺ είναι ο υπηρέτης και ο αγγελιοφόρος Σου.", "Η αφήγηση αναφέρει λέγοντάς το τέσσερις φορές το πρωί.", "Η αφήγηση αναφέρει λέγοντάς το τέσσερις φορές το πρωί."),
    )
}
